1	import { existsSync, mkdirSync } from 'node:fs';
2	import { mkdir, readFile, readdir, rename, rm, writeFile } from 'node:fs/promises';
3	import path from 'node:path';
4	
5	import { canonicalJson, digestOf } from './canonical.js';
6	import { NotFoundError, ValidationError } from './errors.js';
7	
8	const HEX = /^[0-9a-f]{64}$/;
9	
10	function assertHex(value, label) {
11	  if (typeof value !== 'string' || !HEX.test(value)) {
12	    throw new ValidationError(`${label} must be 64 lowercase hex characters`);
13	  }
14	  return value;
15	}
16	
17	// Content-addressed object store. Every byte written lands under the digest of
18	// those exact bytes, so the same content can never occupy two paths and an
19	// existing object is never overwritten with different content.
20	//
21	//   <root>/blobs/sha256/<d0d1>/<digest-hex>      artifact bytes
22	//   <root>/manifests/<k0k1>/<key>.json           node key -> artifact manifest
23	//   <root>/meta/idempotency/<o0o1>/<hex>.json    idempotent response replay
24	//   <root>/meta/stats.json                       lifetime counters
25	//   <root>/meta/actions/<action-id>.json         registered action
26	//   <root>/meta/graphs/<graph-id>.json           registered graph
27	//   <root>/meta/graphs/<graph-id>.last-run.json  last materialized run
28	export class ObjectStore {
29	  constructor(root) {
30	    this.root = path.resolve(root);
31	    this.blobRoot = path.join(this.root, 'blobs', 'sha256');
32	    this.manifestRoot = path.join(this.root, 'manifests');
33	    this.metaRoot = path.join(this.root, 'meta');
34	    for (const directory of [this.blobRoot, this.manifestRoot, this.metaRoot]) {
35	      mkdirSync(directory, { recursive: true });
36	    }
37	  }
38	
39	  blobPath(digest) {
40	    assertHex(digest, 'digest');
41	    return path.join(this.blobRoot, digest.slice(0, 2), digest);
42	  }
43	
44	  manifestPath(key) {
45	    assertHex(key, 'action key');
46	    return path.join(this.manifestRoot, key.slice(0, 2), `${key}.json`);
47	  }
48	
49	  metaPath(...parts) {
50	    return path.join(this.metaRoot, ...parts);
51	  }
52	
53	  hasBlob(digest) {
54	    return existsSync(this.blobPath(digest));
55	  }
56	
57	  hasManifest(key) {
58	    return existsSync(this.manifestPath(key));
59	  }
60	
61	  async writeBlob(buffer) {
62	    const digest = digestOf(buffer).slice('sha256:'.length);
63	    const target = this.blobPath(digest);
64	    await mkdir(path.dirname(target), { recursive: true });
65	    if (!existsSync(target)) {
66	      const temporary = `${target}.tmp-${process.pid}`;
67	      await writeFile(temporary, buffer);
68	      await rename(temporary, target);
69	    }
70	    return digest;
71	  }
72	
73	  // Returns the exact bytes stored for a node key, or throws when the manifest or
74	  // the blob behind it is gone.
75	  async readArtifact(nodeKey) {
76	    const key = assertHex(nodeKey, 'action key');
77	    const manifest = await this.readManifest(key);
78	    const file = this.blobPath(manifest.digest.slice('sha256:'.length));
79	    let buffer;
80	    try {
81	      buffer = await readFile(file);
82	    } catch (error) {
83	      if (error.code === 'ENOENT') {
84	        throw new NotFoundError(`artifact for key ${key} is missing from the object store`);
85	      }
86	      throw error;
87	    }
88	    const actual = digestOf(buffer);
89	    if (actual !== manifest.digest) {
90	      throw new ValidationError(`artifact for key ${key} does not match its manifest digest`);
91	    }
92	    return { manifest, buffer };
93	  }
94	
95	  async writeManifest(nodeKey, manifest) {
96	    const target = this.manifestPath(nodeKey);
97	    await mkdir(path.dirname(target), { recursive: true });
98	    await writeFile(target, `${canonicalJson(manifest)}\n`);
99	    return manifest;
100	  }
101	
102	  async readManifest(nodeKey) {
103	    const key = assertHex(nodeKey, 'action key');
104	    let text;
105	    try {
106	      text = await readFile(this.manifestPath(key), 'utf8');
107	    } catch (error) {
108	      if (error.code === 'ENOENT') {
109	        throw new NotFoundError(`no cache entry exists for key ${key}`);
110	      }
111	      throw error;
112	    }
113	    let manifest;
114	    try {
115	      manifest = JSON.parse(text);
116	    } catch {
117	      throw new ValidationError(`cache manifest for key ${key} is not valid JSON`);
118	    }
119	    if (manifest === null || typeof manifest !== 'object' || manifest.key !== key) {
120	      throw new ValidationError(`cache manifest stored for key ${key} claims a different key`);
121	    }
122	    return manifest;
123	  }
124	
125	  async listKeys(limit = 200) {
126	    const keys = [];
127	    let prefixes;
128	    try {
129	      prefixes = await readdir(this.manifestRoot, { withFileTypes: true });
130	    } catch (error) {
