1	import { readFile, stat } from 'node:fs/promises';
2	import path from 'node:path';
3	
4	import { canonicalJson, digestOf, sha256Text } from './canonical.js';
5	import { ConflictError, NotFoundError, ValidationError } from './errors.js';
6	import { commandSources, executeArtifact, normalizeCommand } from './executor.js';
7	import {
8	  actionIdOf,
9	  actionKey,
10	  assertHash,
11	  assertName,
12	  normalizeCacheInputs,
13	  normalizeEnv,
14	  normalizeInputs,
15	  normalizePath,
16	  runKey,
17	  KEY_SCHEMA,
18	} from './key.js';
19	import { ObjectStore } from './store.js';
20	
21	export const MANIFEST_SCHEMA = 'cachelattice/manifest/v1';
22	export const RUN_SCHEMA = 'cachelattice/run/v1';
23	const STATS_SCHEMA = 'cachelattice/stats/v1';
24	
25	const GRAPH_FIELDS = ['id', 'nodes', 'concurrency'];
26	const NODE_FIELDS = ['id', 'action', 'needs'];
27	const ACTION_FIELDS = ['name', 'command', 'inputs', 'env', 'depends_on'];
28	const INPUT_FIELDS = ['kind', 'path', 'digest'];
29	const CACHE_ENTRY_FIELDS = ['action_id', 'command', 'inputs', 'env', 'depends_on'];
30	
31	const HEX_KEY = /^[0-9a-f]{64}$/;
32	const ZERO_DIGEST = `sha256:${'0'.repeat(64)}`;
33	
34	function rejectUnknown(object, allowed, label) {
35	  for (const key of Object.keys(object)) {
36	    if (!allowed.includes(key)) {
37	      throw new ValidationError(`${label} contains an unknown field: ${key}`);
38	    }
39	  }
40	}
41	
42	function isPlainObject(value) {
43	  return value !== null && typeof value === 'object' && !Array.isArray(value);
44	}
45	
46	function normalizeProducers(value, label) {
47	  if (!Array.isArray(value)) throw new ValidationError(`${label} depends_on must be an array of action names`);
48	  const names = value.map((name) => assertName(name, `${label} dependency`));
49	  if (new Set(names).size !== names.length) {
50	    throw new ValidationError(`${label} lists a dependency twice`);
51	  }
52	  return [...names].sort();
53	}
54	
55	export function assertCacheKey(value) {
56	  if (typeof value !== 'string' || !HEX_KEY.test(value)) {
57	    throw new ValidationError(
58	      `cache key must be 64 lowercase hex characters, received ${JSON.stringify(value)}`,
59	    );
60	  }
61	  return value;
62	}
63	
64	// A node key is only salted when there is something to fold in, which keeps the
65	// root node key of a graph exactly equal to the action key it runs.
66	export function nodeKeyOf(actionKey, upstreamKeys) {
67	  if (upstreamKeys.length === 0) return actionKey;
68	  return sha256Text(
69	    `cachelattice/node-key/v1\n${actionKey}\n${[...upstreamKeys].sort().join('\n')}`,
70	  );
71	}
72	
73	export function dependencyRunKey(dependencies) {
74	  const lines = dependencies
75	    .map((dependency) => `${dependency.action_id}:${dependency.key}`)
76	    .join('\n');
77	  return sha256Text(`cachelattice/dependency-run/v1\n${lines}`);
78	}
79	
80	// A miss and a hit must produce byte-identical manifests as well as
81	// byte-identical artifacts, so the manifest is derived purely from the action
82	// definition, the resolved dependency keys, and the artifact bytes. It carries
83	// no wall-clock timestamp, no node id, and no hint about whether it was
84	// recomputed or read back.
85	export function buildManifest({ actionId, key, command, inputs, env, dependencies, digest, size }) {
86	  return {
87	    schema: MANIFEST_SCHEMA,
88	    key_schema: KEY_SCHEMA,
89	    action_id: actionId,
90	    key,
91	    command,
92	    inputs,
93	    env,
94	    dependency_run_key: dependencyRunKey(dependencies),
95	    dependencies,
96	    digest: `sha256:${digest}`,
97	    size,
98	  };
99	}
100	
101	// Deterministic synthetic execution cost, so a graph run has the same shape on
102	// every machine and concurrency is observable without a real toolchain.
103	function syntheticDelay(command) {
104	  return 10 + (parseInt(sha256Text(canonicalJson(command)).slice(0, 4), 16) % 40);
105	}
106	
107	const sleep = (milliseconds) => new Promise((resolve) => setTimeout(resolve, milliseconds));
108	
109	export class Cachelattice {
110	  constructor({ dataDirectory, workspace, ambientEnv = process.env, clock = () => new Date() }) {
111	    this.store = new ObjectStore(dataDirectory);
112	    this.workspace = path.resolve(workspace);
113	    this.ambientEnv = ambientEnv;
114	    this.clock = clock;
115	    this.actions = new Map();
116	    this.graphs = new Map();
117	    this.runs = new Map();
118	    this.statsCache = null;
119	    this.loading = this.load();
120	  }
121	
122	  async load() {
123	    for (const entry of await this.readRegistry('actions')) this.actions.set(entry.name, entry);
124	    for (const entry of await this.readRegistry('graphs')) this.graphs.set(entry.id, entry);
125	    for (const entry of await this.readRegistry('runs')) this.runs.set(entry.graph_id, entry);
126	    this.statsCache = (await this.store.readMeta('stats.json')) ?? this.blankStats();
127	  }
128	
129	  async readRegistry(kind) {
130	    const index = (await this.store.readMeta(`index/${kind}.json`)) ?? { items: [] };
131	    const items = [];
132	    for (const id of index.items) {
133	      const entry = await this.store.readMeta(`${kind}/${id}.json`);
134	      if (entry) items.push(entry);
135	    }
136	    return items;
137	  }
138	
139	  async writeRegistry(kind, id, entry) {
140	    await this.store.writeMeta(`${kind}/${id}.json`, entry);
141	    const index = (await this.store.readMeta(`index/${kind}.json`)) ?? { items: [] };
142	    if (!index.items.includes(id)) {
143	      await this.store.writeMeta(`index/${kind}.json`, { items: [...index.items, id].sort() });
144	    }
145	    return entry;
146	  }
147	
148	  blankStats() {
149	    return {
150	      schema: STATS_SCHEMA,
151	      actions_registered: 0,
152	      graphs_registered: 0,
153	      graph_runs: 0,
154	      nodes_scheduled: 0,
155	      cache_hits: 0,
156	      cache_misses: 0,
157	      artifacts_executed: 0,
158	      cache_writes: 0,
159	      remote_reads: 0,
160	      remote_writes: 0,
161	      cache_entries: 0,
162	    };
163	  }
164	
165	  async stats() {
166	    await this.loading;
167	    this.statsCache.cache_entries = (await this.store.listKeys(100000)).length;
168	    return { ...this.statsCache };
169	  }
170	
171	  bump(field, amount = 1) {
172	    this.statsCache[field] += amount;
173	  }
174	  async persistStats() {
175	    await this.store.writeMeta('stats.json', this.statsCache);
176	  }
177	
178	  actionView(action) {
179	    return {
180	      name: action.name,
181	      action_id: action.action_id,
182	      key: action.key,
183	      command: action.command,
184	      inputs: action.inputs,
185	      env: action.env.names,
186	      env_values: action.env.values,
187	      depends_on: action.depends_on,
188	    };
189	  }
190	
191	  graphView(graph) {
192	    return { id: graph.id, concurrency: graph.concurrency, nodes: graph.nodes };
193	  }
194	
195	  // ---------------------------------------------------------------- actions
196	
197	  // Validates the declared input list and resolves each entry to the digest that
198	  // enters the key. File inputs are snapshotted here, at registration time, so an
199	  // action key stays stable when the workspace changes underneath it.
200	  async resolveInputs(declaredInputs) {
201	    if (!Array.isArray(declaredInputs) || declaredInputs.length === 0) {
202	      throw new ValidationError('action inputs must be a non-empty array');
203	    }
204	    const declared = normalizeInputs(
205	      declaredInputs.map((input) => {
206	        if (!isPlainObject(input)) throw new ValidationError('each input must be an object');
207	        rejectUnknown(input, INPUT_FIELDS, 'input');
208	        if (input.kind !== 'file' && input.kind !== 'hash') {
209	          throw new ValidationError('input kind must be "file" or "hash"');
210	        }
211	        if (input.kind === 'file' && 'digest' in input) {
212	          throw new ValidationError('a file input must not carry a digest; the service hashes it');
213	        }
214	        if (input.kind === 'hash' && !('digest' in input)) {
215	          throw new ValidationError('a hash input must carry a digest');
216	        }
217	        // normalizeInputs only sorts and de-duplicates; the real digest replaces
218	        // this placeholder below.
219	        return input.kind === 'file' ? { kind: 'file', path: input.path, digest: ZERO_DIGEST } : input;
220	      }),
221	    );
222	    const resolved = [];
223	    for (const input of declared) {
224	      resolved.push(
225	        input.kind === 'hash'
226	          ? { kind: 'hash', path: input.path, digest: assertHash(input.digest, 'input hash') }
227	          : { kind: 'file', path: input.path, digest: digestOf(await readWorkspaceFile(this.workspace, input.path)) },
228	      );
229	    }
230	    return resolved;
231	  }
232	
233	  async putAction(body, { refresh = false } = {}) {
234	    await this.loading;
235	    if (!isPlainObject(body)) throw new ValidationError('request body must be a JSON object');
236	    rejectUnknown(body, ACTION_FIELDS, 'action');
237	    const name = assertName(body.name, 'action name');
238	    if (!isPlainObject(body.command)) throw new ValidationError('action command must be an object');
239	    if (!Array.isArray(body.env)) throw new ValidationError('action env must be an array of names');
240	    const inputs = await this.resolveInputs(body.inputs);
241	
242	    const command = normalizeCommand(body.command);
243	    for (const source of commandSources(command)) {
244	      const normalized = normalizePath(source, 'command source');
245	      if (!inputs.some((input) => input.path === normalized)) {
246	        throw new ValidationError(`command reads ${normalized}, which is not a declared input`);
247	      }
248	    }
249	    if (command.kind === 'concat-text' && command.sources.length === 0) {
250	      throw new ValidationError('command sources must not be empty');
251	    }
252	
253	    // A declared producer must exist and must have produced one of the hash
254	    // inputs. This keeps the causal chain honest: a consumer's key can only move
255	    // for a producer whose artifact it actually consumes.
256	    const dependsOn = normalizeProducers(body.depends_on ?? [], `action ${name}`);
257	    for (const producerName of dependsOn) {
258	      const producer = this.actions.get(producerName);
259	      if (!producer) throw new ValidationError(`action ${name} depends on unregistered action ${producerName}`);
260	      if (!inputs.some((input) => input.kind === 'hash' && input.digest === producer.key)) {
261	        throw new ValidationError(
262	          `action ${name} depends on ${producerName} but does not declare its artifact as a hash input`,
263	        );
264	      }
265	    }
266	    const env = normalizeEnv(body.env, this.ambientEnv);
267	    const entry = {
268	      name,
269	      action_id: actionIdOf(name),
270	      command,
271	      inputs,
272	      env,
273	      // The artifact of every producer named here must be declared as a hash
274	      // input, and the graph must wire exactly these producers as `needs`. The
275	      // producer *keys* are folded into the node key at run time (see plan()),
276	      // which is what makes an upstream change invalidate everything below it.
277	      depends_on: dependsOn,
278	    };
279	    entry.key = actionKey({ command: entry.command, inputs, env });
280	
281	    // A name identifies one action. Registering it again is a conflict no matter
282	    // how similar the definition is, so that replacing an action is always the
283	    // explicit, reviewable act of a PUT.
284	    const previous = this.actions.get(name);
285	    if (previous && !refresh) {
286	      throw new ConflictError(
287	        `action ${name} is already registered; PUT /actions/${name} to replace it`,
288	      );
289	    }
290	    this.actions.set(name, entry);
291	    if (!previous) this.bump('actions_registered');
292	    await this.writeRegistry('actions', name, entry);
293	    await this.persistStats();
294	    return this.actionView(entry);
295	  }
296	
297	  async getAction(name) {
298	    await this.loading;
299	    const entry = this.actions.get(name);
300	    if (!entry) throw new NotFoundError(`action ${name} is not registered`);
301	    return this.actionView(entry);
302	  }
303	
304	  async listActions() {
305	    await this.loading;
306	    return [...this.actions.values()]
307	      .map((action) => this.actionView(action))
308	      .sort((left, right) => (left.name < right.name ? -1 : left.name > right.name ? 1 : 0));
309	  }
310	
311	  // ---------------------------------------------------------------- graphs
312	
313	  async putGraph(graphId, body) {
314	    await this.loading;
315	    const id = assertName(graphId, 'graph id');
316	    if (!isPlainObject(body)) throw new ValidationError('request body must be a JSON object');
317	    rejectUnknown(body, GRAPH_FIELDS, 'graph');
318	    if (body.id !== undefined && body.id !== id) {
319	      throw new ValidationError('graph body id must match the path id');
320	    }
321	    if (!Array.isArray(body.nodes) || body.nodes.length === 0) {
322	      throw new ValidationError('graph nodes must be a non-empty array');
323	    }
324	    const concurrency = body.concurrency === undefined ? 1 : body.concurrency;
325	    if (!Number.isInteger(concurrency) || concurrency < 1 || concurrency > 64) {
326	      throw new ValidationError('graph concurrency must be an integer between 1 and 64');
327	    }
328	
329	    const nodes = body.nodes.map((node) => {
330	      if (!isPlainObject(node)) throw new ValidationError('each graph node must be an object');
331	      rejectUnknown(node, NODE_FIELDS, 'graph node');
332	      const nodeId = assertName(node.id, 'node id');
333	      const action = assertName(node.action, 'node action');
334	      const needs = node.needs === undefined ? [] : node.needs;
335	      if (!Array.isArray(needs)) throw new ValidationError(`node ${nodeId} needs must be an array`);
336	      if (new Set(needs).size !== needs.length) {
337	        throw new ValidationError(`node ${nodeId} lists a dependency twice`);
338	      }
339	      for (const dependency of needs) assertName(dependency, `node ${nodeId} dependency`);
340	      return { id: nodeId, action, needs: [...needs].sort() };
341	    });
342	
343	    const seen = new Set();
344	    for (const node of nodes) {
345	      if (seen.has(node.id)) throw new ValidationError(`duplicate node id: ${node.id}`);
346	      for (const dependency of node.needs) {
347	        if (dependency === node.id) throw new ValidationError(`node ${node.id} needs itself`);
348	        if (!seen.has(dependency)) {
349	          throw new ValidationError(
350	            `node ${node.id} needs ${dependency}, which is not defined earlier in the graph; a dependency cycle is not allowed`,
351	          );
352	        }
353	      }
354	      if (!this.actions.has(node.action)) {
355	        throw new ValidationError(`node ${node.id} references unregistered action ${node.action}`);
356	      }
357	      seen.add(node.id);
358	    }
359	
360	    const entry = { id, concurrency, nodes };
361	    const existed = this.graphs.has(id);
362	    this.graphs.set(id, entry);
363	    if (!existed) this.bump('graphs_registered');
364	    await this.writeRegistry('graphs', id, entry);
365	    await this.persistStats();
366	    return this.graphView(entry);
367	  }
368	
369	  async getGraph(graphId) {
370	    await this.loading;
371	    const graph = this.graphs.get(graphId);
372	    if (!graph) throw new NotFoundError(`graph ${graphId} is not registered`);
373	    const lastRun = this.runs.get(graphId) ?? null;
374	    return {
375	      ...this.graphView(graph),
376	      last_run: lastRun
377	        ? {
378	            run_key: lastRun.run_key,
379	            completed_at: lastRun.completed_at,
380	            duration_ms: lastRun.duration_ms,
381	            peak_parallel: lastRun.peak_parallel,
382	            cache_hits: lastRun.cache_hits,
383	            cache_misses: lastRun.cache_misses,
384	            nodes: lastRun.nodes.map((node) => ({
385	              id: node.id,
386	              action: node.action,
387	              key: node.key,
388	              digest: node.digest,
389	              cache: node.cache,
390	            })),
391	          }
392	        : null,
393	    };
394	  }
395	
396	  async listGraphs() {
397	    await this.loading;
398	    return [...this.graphs.values()]
399	      .map((graph) => this.graphView(graph))
400	      .sort((left, right) => (left.id < right.id ? -1 : left.id > right.id ? 1 : 0));
401	  }
402	
403	  // --------------------------------------------------------------- planning
404	
405	  // Resolves every node to a concrete action key. A node's key folds in the keys
406	  // of every action it needs, so a change anywhere upstream moves every key
407	  // downstream of it.
408	  plan(graphId) {
409	    const graph = this.graphs.get(graphId);
410	    if (!graph) throw new NotFoundError(`graph ${graphId} is not registered`);
411	    const byId = new Map(graph.nodes.map((node) => [node.id, node]));
412	    const planned = new Map();
413	
414	    const visit = (nodeId, trail) => {
415	      const known = planned.get(nodeId);
416	      if (known) return known;
417	      if (trail.has(nodeId)) {
418	        throw new ConflictError(`graph ${graphId} contains a dependency cycle through ${nodeId}`);
419	      }
420	      trail.add(nodeId);
421	      const node = byId.get(nodeId);
422	      if (!node) throw new ValidationError(`graph ${graphId} has no node ${nodeId}`);
423	      const action = this.actions.get(node.action);
424	      if (!action) {
425	        throw new ConflictError(`node ${nodeId} references action ${node.action}, which no longer exists`);
426	      }
427	      const upstream = node.needs.map((needed) => visit(needed, trail));
428	      const produced = upstream.map((entry) => entry.action.name).sort();
429	      const declared = action.depends_on;
430	      if (produced.join('\n') !== declared.join('\n')) {
431	        throw new ConflictError(
432	          `node ${nodeId} is wired to [${produced.join(', ')}] but action ${action.name} declares ` +
433	            `depends_on [${declared.join(', ')}]; re-register the action or rewire the graph`,
434	        );
435	      }
436	      const key = nodeKeyOf(action.key, upstream.map((entry) => entry.key));
437	      trail.delete(nodeId);
438	      const resolved = {
439	        node,
440	        action,
441	        key,
442	        dependencies: upstream
443	          .map((entry) => ({ action_id: entry.action.name, key: entry.key }))
444	          .sort((left, right) =>
445	            left.action_id < right.action_id ? -1 : left.action_id > right.action_id ? 1 : 0,
446	          ),
447	      };
448	      planned.set(nodeId, resolved);
449	      return resolved;
450	    };
451	
452	    for (const node of graph.nodes) visit(node.id, new Set());
453	    return planned;
454	  }
455	
456	  // -------------------------------------------------------------- execution
457	
458	  async runGraph(graphId, { useCache = true } = {}) {
459	    await this.loading;
460	    const graph = this.graphs.get(graphId);
461	    if (!graph) throw new NotFoundError(`graph ${graphId} is not registered`);
462	    const planned = this.plan(graphId);
463	    const key = runKey(
464	      graph.nodes.map((node) => ({ action_id: planned.get(node.id).action.name, key: planned.get(node.id).key })),
465	    );
466	
467	    // A run is always scheduled; there is no whole-run fast path, because the
468	    // answer to "was this a cache hit?" must come from the store on every run.
469	    // `plan_reused` only reports that no key moved since the previous run.
470	    const previous = this.runs.get(graphId) ?? null;
471	    const stale = graph.nodes.flatMap((node) => {
472	      const before = previous?.nodes.find((candidate) => candidate.id === node.id);
473	      const action = planned.get(node.id);
474	      return before && before.key !== action.key
475	        ? [{ id: node.id, action: action.action.name, was: before.key, now: action.key }]
476	        : [];
477	    });
478	    const planReused = previous !== null && previous.run_key === key;
479	
480	    const state = new Map(graph.nodes.map((node) => [node.id, { node, status: 'pending' }]));
481	    const isReady = (id) =>
482	      state.get(id).status === 'pending' &&
483	      state.get(id).node.needs.every((needed) => state.get(needed).status === 'done');
484	    const readyIds = () => graph.nodes.map((node) => node.id).filter(isReady).sort();
485	
486	    let hits = 0;
487	    let misses = 0;
488	    let inFlight = 0;
489	    let peakParallel = 0;
490	    const startedAt = Date.now();
491	    this.bump('graph_runs');
492	    this.bump('nodes_scheduled', graph.nodes.length);
493	
494	    const results = [];
495	    while (results.length < graph.nodes.length) {
496	      // Deterministic dispatch order: lexicographic by node id. Concurrency is
497	      // the only source of timing freedom and never changes an artifact.
498	      while (inFlight < graph.concurrency && readyIds().length > 0) {
499	        const entry = state.get(readyIds()[0]);
500	        entry.status = 'running';
501	        inFlight += 1;
502	        peakParallel = Math.max(peakParallel, inFlight);
503	        const dependencies = entry.node.needs.map((needed) => {
504	          const produced = state.get(needed).result;
505	          return { action_id: produced.action_id, key: produced.key };
506	        });
507	        entry.promise = this.executeNode(planned.get(entry.node.id), dependencies, { useCache })
508	          .then((outcome) => {
509	            entry.status = 'done';
510	            entry.result = outcome;
511	            results.push(outcome);
512	            if (outcome.cache === 'hit') hits += 1;
513	            else misses += 1;
514	          })
515	          .catch((error) => {
516	            entry.status = 'failed';
517	            entry.error = error;
518	          })
519	          .finally(() => {
520	            inFlight -= 1;
521	          });
522	      }
523	      const running = [...state.values()].filter((entry) => entry.status === 'running');
524	      if (running.length === 0) {
525	        // A failed node must surface as a failed request, never as a hang.
526	        const failed = [...state.values()].find((entry) => entry.status === 'failed');
527	        if (failed) throw failed.error;
528	        if (results.length < graph.nodes.length) {
529	          throw new ConflictError(`graph ${graphId} has no schedulable node; check its dependencies`);
530	        }
531	        break;
532	      }
533	      await Promise.all(running.map((entry) => entry.promise));
534	    }
535	
536	    const nodes = results
537	      .map((result) => ({
538	        id: result.id,
539	        action: result.action_id,
540	        key: result.key,
541	        digest: result.digest,
542	        size: result.size,
543	        cache: result.cache,
544	        dependencies: result.dependencies,
545	      }))
546	      .sort((left, right) => (left.id < right.id ? -1 : left.id > right.id ? 1 : 0));
547	
548	    const record = {
549	      schema: RUN_SCHEMA,
550	      graph_id: graphId,
551	      run_key: key,
552	      completed_at: this.clock().toISOString(),
553	      concurrency: graph.concurrency,
554	      duration_ms: Date.now() - startedAt,
555	      peak_parallel: peakParallel,
556	      plan_reused: planReused,
557	      cache_hits: hits,
558	      cache_misses: misses,
559	      stale_nodes: stale,
560	      nodes,
561	    };
562	    this.runs.set(graphId, record);
563	    await this.writeRegistry('runs', graphId, record);
564	    this.bump('cache_hits', hits);
565	    this.bump('cache_misses', misses);
566	    await this.persistStats();
567	
568	    return {
569	      graph_id: graphId,
570	      run_key: key,
571	      plan_reused: planReused,
572	      cache_hits: hits,
573	      cache_misses: misses,
574	      peak_parallel: peakParallel,
575	      stale_nodes: stale,
576	      nodes,
577	    };
578	  }
579	
580	  async executeNode(planned, dependencies, { useCache }) {
581	    const { node, action, key } = planned;
582	    if (useCache && this.store.hasManifest(key)) {
583	      const { manifest } = await this.store.readArtifact(key);
584	      this.assertManifestMatches(manifest, action, key);
585	      return {
586	        id: node.id,
587	        action_id: action.name,
588	        key,
589	        digest: manifest.digest,
590	        size: manifest.size,
591	        cache: 'hit',
592	        dependencies,
593	      };
594	    }
595	
596	    await sleep(syntheticDelay(action.command));
597	    const buffer = await executeArtifact({
598	      command: action.command,
599	      inputs: action.inputs,
600	      env: action.env,
601	      dependencies,
602	      workspace: this.workspace,
603	    });
604	    const digest = await this.store.writeBlob(buffer);
605	    const manifest = buildManifest({
606	      actionId: action.name,
607	      key,
608	      command: action.command,
609	      inputs: action.inputs,
610	      env: action.env,
611	      dependencies,
612	      digest,
613	      size: buffer.length,
614	    });
615	    // A concurrent miss for the same key may have won the race. The manifests
616	    // are identical by construction, so the winner is irrelevant; the blob is
617	    // content-addressed, so there is only ever one possibility.
618	    if (!this.store.hasManifest(key)) await this.store.writeManifest(key, manifest);
619	    this.bump('artifacts_executed');
620	    this.bump('cache_writes');
621	    return {
622	      id: node.id,
623	      action_id: action.name,
624	      key,
625	      digest: manifest.digest,
626	      size: manifest.size,
627	      cache: 'miss',
628	      dependencies,
629	    };
630	  }
631	
632	  // ---------------------------------------------------------------- verify
633	
634	  // Re-executes the graph with cache reads disabled and compares every node with
635	  // what the cache already holds, by digest and byte by byte. A cache entry that
636	  // cannot even be read back (missing blob, tampered bytes) is reported as an
637	  // issue rather than raised, because that is exactly what verification is for.
638	  async verifyGraph(graphId) {
639	    await this.loading;
640	    const baseline = this.runs.get(graphId);
641	    if (!baseline) throw new NotFoundError(`graph ${graphId} has no completed run to verify`);
642	    const cached = new Map();
643	    const issues = [];
644	    for (const node of baseline.nodes) {
645	      try {
646	        const entry = await this.store.readArtifact(node.key);
647	        cached.set(node.id, { digest: node.digest, buffer: entry.buffer });
648	      } catch (error) {
649	        issues.push({ id: node.id, issue: 'cache_unreadable', detail: error.message });
650	      }
651	    }
652	    const rerun = await this.runGraph(graphId, { useCache: false });
653	    let byteIdentical = 0;
654	    for (const node of rerun.nodes) {
655	      const before = cached.get(node.id);
656	      if (!before) {
657	        if (!issues.some((issue) => issue.id === node.id)) {
658	          issues.push({ id: node.id, issue: 'missing_from_baseline' });
659	        }
660	        continue;
661	      }
662	      if (before.digest !== node.digest) {
663	        issues.push({ id: node.id, issue: 'digest_changed', cached: before.digest, recomputed: node.digest });
664	        continue;
665	      }
666	      let after;
667	      try {
668	        after = await this.store.readArtifact(node.key);
669	      } catch (error) {
670	        issues.push({ id: node.id, issue: 'cache_unreadable', detail: error.message });
671	        continue;
672	      }
673	      if (before.buffer.equals(after.buffer)) byteIdentical += 1;
674	      else issues.push({ id: node.id, issue: 'bytes_differ', digest: node.digest });
675	    }
676	    return {
677	      graph_id: graphId,
678	      run_key: rerun.run_key,
679	      identical: issues.length === 0,
680	      comparisons: rerun.nodes.length,
681	      byte_identical: byteIdentical,
682	      issues,
683	    };
684	  }
685	
686	  // ----------------------------------------------------------------- cache
687	
688	  async cacheGet(key) {
689	    await this.loading;
690	    const normalized = assertCacheKey(key);
691	    const { manifest, buffer } = await this.store.readArtifact(normalized);
692	    return { manifest, buffer };
693	  }
694	
695	  // Ingest an action manifest. Any peer that knows a cached action key may push
696	  // the entry, and it is accepted only when every hashed field in the manifest
697	  // still recomputes to the key being claimed.
698	  async cachePut(key, entry, buffer) {
699	    await this.loading;
700	    const normalized = assertCacheKey(key);
701	    if (!isPlainObject(entry)) throw new ValidationError('cache entry must be a JSON object');
702	    rejectUnknown(entry, CACHE_ENTRY_FIELDS, 'cache entry');
703	    if (!isPlainObject(entry.command)) throw new ValidationError('cache entry command must be an object');
704	    if (!Array.isArray(entry.inputs) || !Array.isArray(entry.env)) {
705	      throw new ValidationError('cache entry inputs and env must be arrays');
706	    }
707	    for (const input of entry.inputs) {
708	      if (!isPlainObject(input)) throw new ValidationError('cache entry inputs must be objects');
709	      rejectUnknown(input, INPUT_FIELDS, 'cache entry input');
710	      if (input.kind !== 'file' && input.kind !== 'hash') {
711	        throw new ValidationError('cache entry input kind must be "file" or "hash"');
712	      }
713	    }
714	    const command = normalizeCommand(entry.command);
715	    const inputsValue = normalizeCacheInputs(entry.inputs);
716	    const names = entry.env.map((name) => {
717	      if (typeof name !== 'string' || !/^[A-Za-z_][A-Za-z0-9_]*$/.test(name)) {
718	        throw new ValidationError('cache entry env must be an array of variable names');
719	      }
720	      return name;
721	    });
722	    if (new Set(names).size !== names.length) {
723	      throw new ValidationError('cache entry env names must be unique');
724	    }
725	    // Copied so the manifest never aliases caller-owned state.
726	    const inputs = inputsValue.map((input) => ({ ...input }));
727	    const env = { names: [...names].sort(), values: {} };
728	    const recomputed = actionKey({ command, inputs, env });
729	    if (recomputed !== normalized) {
730	      throw new ValidationError(
731	        `cache entry does not describe key ${normalized}: the same fields hash to ${recomputed}`,
732	      );
733	    }
734	    const manifestKey = normalized;
735	    if (this.store.hasManifest(manifestKey)) {
736	      throw new ConflictError(`cache entry ${normalized} already exists`);
737	    }
738	    const digest = await this.store.writeBlob(buffer);
739	    // A remote entry carries no resolved dependency keys, so it is only ever
740	    // reachable as the entry of a root node - exactly the entries a peer can
741	    // hand over without shipping its whole graph.
742	    const manifest = buildManifest({
743	      actionId: entry.action_id ?? 'remote',
744	      key: normalized,
745	      command,
746	      inputs,
747	      env,
748	      dependencies: [],
749	      digest,
750	      size: buffer.length,
751	    });
752	    await this.store.writeManifest(manifestKey, manifest);
753	    this.bump('remote_writes');
754	    this.bump('cache_writes');
755	    await this.persistStats();
756	    return manifest;
757	  }
758	
759	  async remoteRead(key) {
760	    await this.loading;
761	    const entry = await this.cacheGet(key);
762	    this.bump('remote_reads');
763	    await this.persistStats();
764	    return entry;
765	  }
766	
767	  async cacheEntries(limit = 500) {
768	    await this.loading;
769	    return this.store.listKeys(limit);
770	  }
771	
772	  // ----------------------------------------------------------- idempotency
773	
774	  async recall(operation, idempotencyKey) {
775	    await this.loading;
776	    if (typeof idempotencyKey !== 'string' || idempotencyKey.length === 0) return null;
777	    if (idempotencyKey.length > 255) {
778	      throw new ValidationError('Idempotency-Key must be at most 255 characters');
779	    }
780	    const record = await this.store.readMeta(
781	      `idempotency/${sha256Text(`${operation}\n${idempotencyKey}`)}.json`,
782	    );
783	    return record ? { status: record.status, body: record.body } : null;
784	  }
785	
786	  async remember(operation, idempotencyKey, response) {
787	    await this.loading;
788	    if (typeof idempotencyKey !== 'string' || idempotencyKey.length === 0) return;
789	    await this.store.writeMeta(
790	      `idempotency/${sha256Text(`${operation}\n${idempotencyKey}`)}.json`,
791	      {
792	        schema: 'cachelattice/idempotency/v1',
793	        operation,
794	        status: response.status,
795	        body: response.body,
796	      },
797	    );
798	  }
799	
800	  // A cache entry is valid for a node when the manifest's hashed fields still
801	  // describe the action the node runs: same command, same input digests, same
802	  // environment variable names. The action_id is provenance only - two
803	  // differently named actions with the same definition legitimately share one
804	  // entry, and the first one to run wins the label.
805	  assertManifestMatches(manifest, action, key) {
806	    if (manifest.key !== key) {
807	      throw new ConflictError(`cache entry ${key} claims to belong to ${manifest.key}`);
808	    }
809	    const shape = (command, inputs, envNames) =>
810	      canonicalJson({ command, inputs, env_names: envNames });
811	    if (
812	      shape(manifest.command, manifest.inputs, manifest.env.names) !==
813	      shape(action.command, action.inputs, action.env.names)
814	    ) {
815	      throw new ConflictError(`cache entry for ${key} was produced from different inputs`);
816	    }
817	  }
818	}
819	
820	export async function readWorkspaceFile(workspace, relative) {
821	  const absolute = path.join(workspace, relative);
822	  if (absolute !== workspace && !absolute.startsWith(workspace + path.sep)) {
823	    throw new ValidationError(`path escapes the workspace: ${relative}`);
824	  }
825	  let info;
826	  try {
827	    info = await stat(absolute);
828	  } catch (error) {
829	    if (error.code === 'ENOENT') throw new ValidationError(`input file does not exist: ${relative}`);
830	    throw error;
831	  }
832	  if (!info.isFile()) throw new ValidationError(`input path is not a regular file: ${relative}`);
833	  return readFile(absolute);
834	}
