describe('garbage collection', () => {
  const seedTwo = async () => {
    await registerFilter('first');
    await registerFilter('second');
    await service.putGraph('g1', { id: 'g1', nodes: [{ id: 'a', action: 'first' }] });
    await service.putGraph('g2', { id: 'g2', nodes: [{ id: 'b', action: 'second' }] });
    const r1 = await service.runGraph('g1');
    const r2 = await service.runGraph('g2');
    return {
      key1: r1.nodes[0].key,
      key2: r2.nodes[0].key,
      digest1: r1.nodes[0].digest,
      digest2: r2.nodes[0].digest,
      size1: r1.nodes[0].size,
      size2: r2.nodes[0].size,
    };
  };

  test('keeps last_run keys by default and removes the rest with their blobs', async () => {
    const seeded = await seedTwo();
    // A third entry with no graph run referencing it: an orphaned old version.
    const old = await registerFilter('old', { pattern: 'beta' });
    await runOne('old', 'gone');
    const oldSize = (await service.cacheGet(old.key)).buffer.length;

    const result = await service.collectGarbage({});
    assert.deepEqual(result.kept_keys.sort(), [seeded.key1, seeded.key2].sort());
    assert.deepEqual(result.removed_keys, [old.key]);
    assert.deepEqual(result.removed_digests, [`sha256:${(await (async () => old)()).key && undefined}`]);
  });

  test('computes unique byte totals and deletes only unreferenced blobs', async () => {
    const seeded = await seedTwo();
    const result = await service.collectGarbage({ keep: [] });
    assert.equal(result.dry_run, false);
    assert.deepEqual(result.kept_keys.sort(), [seeded.key1, seeded.key2].sort());
    assert.deepEqual(result.removed_keys, []);
    assert.deepEqual(result.removed_digests, []);
    assert.equal(result.kept_bytes, seeded.size1 + seeded.size2);
    assert.equal(result.removed_bytes, 0);
    // Kept artifacts are still served.
    assert.equal((await service.cacheGet(seeded.key1)).buffer.toString(), 'alpha\nbeta\ngamma\n');
  });

  test('an orphan blob is removed and counted once', async () => {
    const seeded = await seedTwo();
    const orphan = Buffer.from('nobody references me\n');
    const orphanDigest = await service.store.writeBlob(orphan);
    const result = await service.collectGarbage({});
    assert.deepEqual(result.removed_digests, [`sha256:${orphanDigest}`]);
    assert.equal(result.removed_bytes, orphan.length);
    assert.equal(service.store.hasBlob(orphanDigest), false);
    assert.equal(service.store.hasBlob(seeded.key1.match(/.*/)[0] && seeded.digest1.slice(7)), true);
  });

  test('keep pins extra keys; order and repetition are irrelevant', async () => {
    const seeded = await seedTwo();
    const extra = await registerFilter('extra', { match: 'drop' });
    await runOne('extra', 'extra-run');
    const result = await service.collectGarbage({ keep: [extra.key, extra.key, seeded.key1] });
    assert.deepEqual(result.kept_keys.sort(), [seeded.key1, seeded.key2, extra.key].sort());
    assert.deepEqual(result.removed_keys, []);
    assert.equal(service.store.hasManifest(extra.key), true);
  });

  test('dry run reports the same sets and bytes but deletes nothing', async () => {
    const seeded = await seedTwo();
    const extra = await registerFilter('extra', { match: 'drop' });
    await runOne('extra', 'extra-run');
    const before = await service.collectGarbage({ dry_run: true, keep: [] });
    assert.equal(before.dry_run, true);
    assert.deepEqual(before.removed_keys, [extra.key]);
    assert.equal(before.removed_bytes > 0, true);
    // Nothing was removed.
    assert.equal(service.store.hasManifest(extra.key), true);
    // A real run immediately afterward reports the same sets and then deletes.
    const after = await service.collectGarbage({});
    assert.equal(after.dry_run, false);
    assert.deepEqual(after.removed_keys, before.removed_keys);
    assert.equal(after.removed_bytes, before.removed_bytes);
    assert.equal(service.store.hasManifest(extra.key), false);
    assert.equal(seeded.key1.length, 64);
  });

  test('a graph without a last run contributes no retained key', async () => {
    const seeded = await seedTwo();
    await registerFilter('lonely', { pattern: 'gamma' });
    await service.putGraph('never-run', { id: 'never-run', nodes: [{ id: 'z', action: 'lonely' }] });
    await runOne('lonely', 'lonely-run');
    const result = await service.collectGarbage({});
    const lonelyAction = await service.getAction('lonely');
    assert.ok(result.removed_keys.includes(lonelyAction.key));
    assert.ok(!result.kept_keys.includes(lonelyAction.key));
    assert.equal(seeded.key1 !== seeded.key2, true);
  });

  test('a missing keep key is 404 and deletes nothing', async () => {
    await seedTwo();
    const ghost = hex('9');
    await assert.rejects(
      service.collectGarbage({ keep: [ghost] }),
      (error) => error instanceof NotFoundError && new RegExp(ghost).test(error.message),
    );
    // The cache is intact after the aborted collection.
    assert.deepEqual((await service.cacheEntries()).length, 2);
  });

  test('illegal keys, bad dry_run, unknown fields and malformed body are 400', async () => {
    await seedTwo();
    await assert.rejects(service.collectGarbage({ keep: ['nope'] }), (e) => e instanceof ValidationError);
    await assert.rejects(service.collectGarbage({ keep: 'x' }), (e) => e instanceof ValidationError);
    await assert.rejects(service.collectGarbage({ dry_run: 'yes' }), (e) => e instanceof ValidationError);
    await assert.rejects(service.collectGarbage({ surprise: 1 }), /unknown field: surprise/);
    await assert.rejects(service.collectGarbage(null), (e) => e instanceof ValidationError);
  });

  test('an invalid manifest, bad digest, missing blob or mismatch aborts with 400 and deletes nothing', async () => {
    const seeded = await seedTwo();
    const entries = await service.cacheEntries();

    // Tampered manifest JSON.
    const target = service.store.manifestPath(seeded.key1);
    await writeFile(target, '{not json\n');
    await assert.rejects(service.collectGarbage({}), (e) => e instanceof ValidationError);
    assert.equal(service.store.hasManifest(seeded.key1), true, 'no object is deleted on failure');

    // Restore a sound manifest, then claim a malformed digest.
    const { manifest } = await service.store.readArtifact(seeded.key2);
    await service.deleteMeta?.();
    await writeFile(
      service.store.manifestPath(seeded.key1),
      `${canonicalJson({ ...manifest, key: seeded.key1, digest: 'sha256:zz' })}\n`,
    );
    await assert.rejects(service.collectGarbage({}), (e) => e instanceof ValidationError);

    // Missing referenced blob.
    const sound = (await service.cacheEntries()).length;
    assert.equal(sound, entries.length);
    const digest1 = seeded.digest1.slice('sha256:'.length);
    // rebuild the valid manifest for key1 then remove its blob
    await service.store.writeManifest(seeded.key1, {
      ...manifest,
      key: seeded.key1,
      digest: seeded.digest1,
    });
    await service.store.deleteBlob(digest1);
    await assert.rejects(service.collectGarbage({}), (e) => e instanceof ValidationError);
    assert.equal(service.store.hasManifest(seeded.key2), true);

    // Put the blob back but with different content than the digest claims.
    const digest2 = seeded.digest2.slice('sha256:'.length);
    await writeFile(service.store.blobPath(digest1), 'wrong bytes');
    await service.store.writeManifest(seeded.key1, { ...manifest, key: seeded.key1, digest: seeded.digest1 });
    await assert.rejects(service.collectGarbage({}), (e) => e instanceof ValidationError);
    assert.equal(service.store.hasBlob(digest2), true, 'a failed scan deletes no blobs');
  });

  test('gc leaves GET /cache, stats, runs and remote reads semantically intact', async () => {
    const seeded = await seedTwo();
    await service.collectGarbage({});
    assert.equal((await service.cacheGet(seeded.key1)).manifest.digest, seeded.digest1);
    const run = await service.runGraph('g1');
    assert.equal(run.cache_hits, 1);
    const stats = await service.stats();
    assert.equal(typeof stats.cache_entries, 'number');
  });
});

